    "sourceHash": "sha256:a2e4da08f1e62e1418eb7a29bb9bb8a49cc96537e14e973f90a13aba72da844b",
    "translatableHash": "sha256:f6675f403dfdc3edf4e0cedf8cc392d5166e56dc11601260b76c26473bea9ce0",
    "data": {
      "schemaVersion": 1,
      "name": "Bright Walker",
      "level": 9,
      "rarity": "rare",
      "size": "medium",
      "traits": [
        "evil",
        "incorporeal",
        "spirit",
        "undead",
        "unholy"
      ],
      "description": "Those who encounter calignis quickly learn that their deaths involve burning out instead of bleeding out. At times, this dramatic immolation is denied to a caligni, so they arise as a bright walker. Tied to caligni society, these creatures don't understand that their glow damages and repels living calignis. Despite their name, these undead don't walk; they instead float a few inches above the ground.",
      "armorClass": 26,
      "hitPoints": 115,
      "speedFeet": 0,
      "perception": {
        "modifier": 19,
        "senses": [
          "greater-darkvision"
        ]
      },
      "saves": {
        "fortitude": 15,
        "reflex": 21,
        "will": 19
      },
      "abilities": {
        "str": -5,
        "dex": 6,
        "con": 0,
        "int": 0,
        "wis": 4,
        "cha": 3
      },
      "skills": {
        "acrobatics": 19,
        "intimidation": 18,
        "stealth": 19
      },
      "languages": [
        "caligni"
      ],
      "defenses": {
        "immunities": [
          "bleed",
          "death-effects",
          "disease",
          "paralyzed",
          "poison",
          "precision",
          "unconscious"
        ],
        "resistances": [
          "all-damage 10 except force, ghost-touch, vitality"
        ],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "LBtHMsDMDaIqyB7z",
          "name": "Radiant Touch",
          "bonus": 21,
          "damage": "2d8+11 fire",
          "traits": [
            "agile",
            "finesse",
            "fire",
            "light",
            "magical"
          ]
        },
        {
          "id": "eZxgYfIRD41tf3F9",
          "name": "Radiant Ray",
          "bonus": 21,
          "damage": "2d6+11 fire",
          "traits": [
            "fire",
            "light",
            "magical"
          ]
        }
      ],
      "actions": [
        {
          "id": "rq016ZULtzeq5Jdo",
          "name": "Greater Darkvision",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "06lGWrOe3DOYvTgV",
          "name": "Bright Release",
          "kind": "passive",
          "description": "When a bright walker is reduced to 0 Hit Points, they flash out in a burst of light, obtaining the blazing end they were denied at death. This blaze deals 10d6 fire damage (check (reflex, dc:25, basic, options:area-effect) save) to creatures within 20-foot emanation.\nCreatures who fail this save are also Dazzled for 1 minute (Blinded for 1 minute on a critical failure).",
          "traits": [
            "fire",
            "light"
          ]
        },
        {
          "id": "1SovHiGHboDM9yGe",
          "name": "Light Aura",
          "kind": "passive",
          "description": "30 feet. The bright walker sheds bright light. Any creature that starts its turn in the aura must attempt at a check (fortitude, dc:24) save.\nCritical Success The creature is temporarily immune for 24 hours.\nSuccess The creature is Dazzled for 1 round.\nFailure The creature is Blinded for 1 round.\nCritical Failure The creature is blinded for 1 hour.",
          "traits": [
            "aura",
            "divine",
            "light"
          ]
        },
        {
          "id": "cb5fpVrLbNcM4VUi",
          "name": "Suppress Aura",
          "kind": "action",
          "description": "The bright walker suppresses their light aura for 1 round, reducing it to a faint, ghostly glow of dim light.",
          "traits": [
            "concentrate"
          ]
        },
        {
          "id": "oviUeLIMpj5EZvoL",
          "name": "Void Healing",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "hwqvhAAeZ5lZGags",
          "name": "Landbound",
          "kind": "passive",
          "description": "A bright walker can't fly higher than 1 foot above the ground. If they fly higher than this distance, they fall but don't take any damage from falling.",
          "traits": []
        },
        {
          "id": "6pIoss4a281w0Fed",
          "name": "Light Flare",
          "kind": "action",
          "description": "Requirement The bright walker's Light Aura is suppressed\nEffect The bright walker reignites their Light Aura with a burst of brightness that deals 5d6 fire damage (check (reflex, dc:25, basic, options:area-effect) save) to creatures within a 20-foot burst.\nCreatures who are Dazzled or with Light Blindness find this flare particularly painful; such a creature's save result is one degree of success worse than the result it rolled.",
          "traits": [
            "divine",
            "fire",
            "light"
          ]
        },
        {
          "id": "GA3sOIQc3gtd1dyN",
          "name": "Shadow Jump",
          "kind": "action",
          "description": "Requirement The bright walker's Light Aura is suppressed\nEffect The bright walker teleports to a square it can see within 60 feet that is not in an area of bright light. The bright walker can't use again for 1d4.",
          "traits": [
            "divine",
            "teleportation"
          ]
        }
      ],
      "spellcasting": []
    }
