        {
          "id": "aT1K6zkwI73D4tJ8",
          "name": "Poisoned Coat",
          "kind": "reaction",
          "description": "Trigger A creature adjacent to Blue Viper hits him with a melee unarmed Strike.\nEffect The triggering creature is exposed to Dragon Bile. This consumes the poison, and Blue Viper can't use Poisoned Coat again until he spends 10 minutes applying one dose of contact or injury poison to his clothing.",
          "traits": []
        },
        {
          "id": "G1wu8KW1gALb7KbD",
          "name": "Pinpoint Poisoner",
          "kind": "passive",
          "description": "When Blue Viper successfully Strikes an Off-Guard creature with a poisoned weapon or exposes an off-guard creature to an inhaled poison, the creature takes a –2 circumstance penalty to its initial save against that poison.\nEffect: Pinpoint Poisoner",
          "traits": []
        },
        {
          "id": "sUXeC5liFm6oJVn7",
          "name": "Plum Rain Deluge",
          "kind": "action",
          "description": "Frequency once per round\nEffect Blue Viper accelerates the flow of time so his poisons run their course faster. He Interacts to draw a contact poison and throws it in the air, where it showers down in a 20-foot burst within 60 feet. All creatures in the burst are automatically exposed to the poison, bypassing any onset time, and each creature must attempt a saving throw against that poison. If a creature fails, the duration of any beneficial spells or effects affecting the creature are reduced by 3 rounds (or by 6 rounds on a critical failure).",
          "traits": [
            "certain-kill"
          ]
        },
        {
          "id": "Tt37ijMg1fiX7fGx",
          "name": "Poison Spray",
          "kind": "action",
          "description": "Requirements Blue Viper is holding a contact or injury poison.\nEffect Blue Viper swigs the poison and sprays it out of his mouth, affecting a 15-foot cone. Blue Viper isn't exposed to the poison. All creatures in the cone are immediately exposed to the poison and each creature must attempt a Fortitude save against the poison.",
          "traits": []
        },
        {
          "id": "rbtSqixbTXvvcmJc",
          "name": "Potent Poisoner",
          "kind": "passive",
          "description": "Blue Viper's infused poisons have a DC of 47.",
          "traits": []
        },
        {
          "id": "UUgL7mamcQM9PkU0",
          "name": "Quick Application",
          "kind": "action",
          "description": "Blue Viper Interacts to draw an injury poison and applies it to a weapon he is holding.",
          "traits": []
        },
        {
          "id": "TJSUkfiilrbozvGh",
          "name": "Quick Bomber",
          "kind": "action",
          "description": "Blue Viper Interacts to draw a bomb, then Strikes with it.",
          "traits": []
        },
        {
          "id": "KNsjthb0m0ASdoMo",
          "name": "Toxic Escape",
          "kind": "action",
          "description": "Blue Viper Interacts to draw an inhaled poison, deploys the poison in a smoke cloud that provides concealment in a 5-foot emanation, then Sneaks up to his Speed. He is not exposed to the inhaled poison.",
          "traits": []
        }
